from itertools import product, combinations
import heapq


def _ledger(revision_priority, tax_base):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            revision = event.get("revision", 0)
            if revision_priority == "sequence_first":
                priority = (sequence, revision, position)
            else:
                priority = (revision, position)
            if event_id not in chosen or priority > chosen[event_id][0]:
                chosen[event_id] = (priority, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains.append([None] + versions)

        best_vector = None
        best_installation = None
        for choices in product(*domains):
            assigned = dict(zip(names, choices))
            if any(assigned.get(name) is None or
                   not low <= assigned[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            installed = {name for name, version in assigned.items()
                         if version is not None}
            closure = set()
            edges = {name: [] for name in installed}
            stack = list(roots)
            feasible = True
            while stack and feasible:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                version = assigned.get(name)
                if version is None:
                    feasible = False
                    break
                row = next((row for row in packages[name]
                            if row["version"] == version), None)
                if row is None:
                    feasible = False
                    break
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = assigned.get(other)
                    if (other_version is None or
                            not dep["min"] <= other_version <= dep["max"]):
                        feasible = False
                        break
                    edges[name].append(other)
                    stack.append(other)
            if not feasible or closure != installed:
                continue

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in installed):
                continue
            vector = tuple(assigned[name] if assigned[name] is not None else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_installation = {name: assigned[name] for name in names
                                     if assigned[name] is not None}

        if best_installation is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_installation}
    return solve


def _component_07():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            points = {job["start"] for job in subset}
            if any(sum(job["start"] <= point < job["end"] for job in subset) > 2
                   for point in points):
                continue
            value = sum(job["value"] for job in subset)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids > best_ids)):
                best_value, best_ids = value, sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _component_08():
    def solve(data):
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        required = data.get("required", [])
        bits = {node: 1 << index for index, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        source, target = data["source"], data["target"]
        coupons = data["coupons"]
        initial_mask = bits.get(source, 0)
        initial_state = (source, initial_mask, coupons)
        distances = {initial_state: data["start"]}
        queue = [(data["start"], source, initial_mask, coupons)]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == target and mask == full_mask:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                duration = edge["duration"]
                options = [(duration, remaining)]
                if remaining:
                    discounted = max(1, duration - edge.get("discount", 0))
                    options.append((discounted, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                for travel_time, next_remaining in options:
                    arrival = depart + travel_time
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _ledger("revision_first", "original"),
    "component_02": _ledger("sequence_first", "original"),
    "component_03": _ledger("revision_first", "discounted"),
    "component_04": _ledger("sequence_first", "discounted"),
    "component_05": _ledger("revision_first", "original"),
    "component_06": _component_06(),
    "component_07": _component_07(),
    "component_08": _component_08(),
}
